# generated by tools/ail2py.py from csv_rewrite_main.ail; edit the .ail until onelang s16
from csv_writer import *
from csv_stream import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

# Whole-file normalization, not an unbounded streaming interface.
# Existing CSV decoder ignores blank records; emitted records always end CRLF.
# Input validation precedes output opening; output write failures are not atomic.
def main() -> int:
    if len(sys.argv) != 3:
        print('usage: csv_rewrite INPUT OUTPUT', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        output: str = sys.argv[2]
        if input == output or file_paths_same(input, output):
            raise ValueError
        text: str = read_bytes(input).decode('utf-8')
        decoder: CsvDecoder = csv_decoder_new()
        rows: list[CsvRow] = csv_decode_feed(decoder, text)
        rows.extend(csv_decode_finish(decoder))
        parts: list[str] = []
        for row in rows:
            parts.append(csv_encode_row(row.fields))
        encoded: bytes = ''.join(parts).encode('utf-8')
        write_bytes(output, encoded)
        return 0
    except UnicodeDecodeError:
        print('invalid UTF-8 CSV input', file=sys.stderr)
        return 4
    except ValueError:
        print('invalid CSV input or output alias', file=sys.stderr)
        return 4
    except OSError:
        print('CSV rewrite file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
